  "test": "import { describe, expect, it } from 'vitest';
import { priceCart, CartLine, Promotion } from '../src/pricing';

describe('regresión cupón fijo', () => {
  it('aplica el cupón de monto fijo una única vez al total y no por cada línea', () => {
    const lines: CartLine[] = [
      { sku: 'ITEM-1', qty: 1, unitPriceCents: 10000, category: 'general' },
      { sku: 'ITEM-2', qty: 1, unitPriceCents: 15000, category: 'general' },
    ];

    const promotions: Promotion[] = [
      { type: 'COUPON_FIXED', code: 'DESC10', amountCents: 1000, minPurchaseCents: 20000 },
    ];

    const result = priceCart(lines, promotions, 'DESC10');

    expect(result.subtotalCents).toBe(25000);
    expect(result.discountCents).toBe(1000);
    expect(result.totalCents).toBe(24000);
  });
});
